-- manifest: camada CarlosCostaPrev (antiga 0166, renumerada para 8008 em 13/11/2026; o timestamp nao mudou): previdenciario knowledge base
-- PREV-007: base de conhecimento previdenciária curada e versionada.
-- Conteúdo clínico importado como referência needs_review; não é diagnóstico nem decisão jurídica.
-- CID, CIF e IFBrA permanecem em colunas/tabelas distintas por desenho.

create table if not exists public.previdenciario_pathology_knowledge (
  id uuid primary key default gen_random_uuid(),
  stable_key text not null unique check (stable_key ~ '^[a-z0-9][a-z0-9_]{2,119}$'),
  display_name text not null,
  category text not null,
  aliases text[] not null default '{}'::text[],
  cid10_codes text[] not null default '{}'::text[],
  cid11_codes text[] not null default '{}'::text[],
  cif_body_functions text[] not null default '{}'::text[],
  cif_body_structures text[] not null default '{}'::text[],
  cif_activities_participation text[] not null default '{}'::text[],
  cif_environmental_factors text[] not null default '{}'::text[],
  ifbra_instrument_version text,
  ifbra_domains text[] not null default '{}'::text[],
  ifbra_activities text[] not null default '{}'::text[],
  clinical_content jsonb not null default '{}'::jsonb,
  benefit_hypotheses jsonb not null default '[]'::jsonb,
  service_links text[] not null default '{}'::text[],
  source_repo text not null default 'sistemaprev' check (source_repo = 'sistemaprev'),
  source_path text not null,
  source_line integer check (source_line is null or source_line > 0),
  source_commit text not null,
  source_snapshot_sha256 text not null check (source_snapshot_sha256 ~ '^[a-f0-9]{64}$'),
  review_status text not null default 'needs_review' check (review_status in ('draft','needs_review','approved','rejected','archived')) ,
  reviewer_user_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.previdenciario_ifbra_items (
  id uuid primary key default gen_random_uuid(),
  instrument_version text not null default 'Portaria Conjunta MDS/INSS nº 2/2015',
  domain_key text not null check (domain_key in ('bodyFunctions','bodyStructures','activitiesParticipation','environmentalFactors')) ,
  domain_label text not null,
  domain_description text not null,
  code text not null,
  label text not null,
  source_repo text not null default 'sistemaprev' check (source_repo = 'sistemaprev'),
  source_path text not null,
  source_commit text not null,
  source_snapshot_sha256 text not null check (source_snapshot_sha256 ~ '^[a-f0-9]{64}$'),
  review_status text not null default 'needs_review' check (review_status in ('draft','needs_review','approved','rejected','archived')) ,
  reviewer_user_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (instrument_version, code)
);

create table if not exists public.previdenciario_ifbra_qualifiers (
  value smallint primary key check (value between 0 and 4),
  label text not null,
  range_label text not null,
  source_repo text not null default 'sistemaprev' check (source_repo = 'sistemaprev'),
  source_path text not null,
  source_commit text not null,
  source_snapshot_sha256 text not null check (source_snapshot_sha256 ~ '^[a-f0-9]{64}$'),
  review_status text not null default 'needs_review' check (review_status in ('draft','needs_review','approved','rejected','archived')) ,
  reviewer_user_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now());

create table if not exists public.previdenciario_legal_sources (
  id uuid primary key default gen_random_uuid(),
  source_key text not null unique,
  title text not null,
  source_type text not null check (source_type in ('official_law','official_regulation','official_guidance')) ,
  official_url text not null,
  jurisdiction text not null default 'Brasil',
  accessed_at date not null,
  source_version text,
  source_snapshot_sha256 text,
  review_status text not null default 'needs_review' check (review_status in ('draft','needs_review','approved','rejected','archived')) ,
  reviewer_user_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now());

create table if not exists public.previdenciario_legal_crosswalk (
  id uuid primary key default gen_random_uuid(),
  benefit_catalog_item_id uuid not null references public.previdenciario_catalog_items(id) on delete cascade,
  legal_source_id uuid not null references public.previdenciario_legal_sources(id) on delete cascade,
  provision_ref text not null,
  relation_type text not null check (relation_type in ('defines_requirement','defines_exception','defines_document','defines_deadline','defines_procedure','historical_context','not_applicable')) ,
  summary text not null,
  case_date_rule text,
  review_status text not null default 'needs_review' check (review_status in ('draft','needs_review','approved','rejected','archived')) ,
  confidence text not null default 'unknown' check (confidence in ('unknown','low','medium','high')) ,
  reviewer_user_id uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (benefit_catalog_item_id, legal_source_id, provision_ref, relation_type)
);

create index if not exists previdenciario_pathology_category_idx on public.previdenciario_pathology_knowledge (category, review_status);
create index if not exists previdenciario_pathology_cid10_gin_idx on public.previdenciario_pathology_knowledge using gin (cid10_codes);
create index if not exists previdenciario_pathology_cid11_gin_idx on public.previdenciario_pathology_knowledge using gin (cid11_codes);
create index if not exists previdenciario_ifbra_domain_idx on public.previdenciario_ifbra_items (instrument_version, domain_key, review_status);
create index if not exists previdenciario_crosswalk_benefit_idx on public.previdenciario_legal_crosswalk (benefit_catalog_item_id, review_status);

